// Reads the catalog (copied from the app by scripts/copy-data.mjs) and the
// seed tables (generated by tool/gen_seeds.dart) from functions/data/.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

import { validateData, type Catalog, type SeedTables } from '../domain/catalog';

const dataDir = join(__dirname, '..', '..', 'data');

export function loadData(): { catalog: Catalog; tables: SeedTables } {
  const catalog = JSON.parse(readFileSync(join(dataDir, 'catalog.json'), 'utf8')) as Catalog;
  const tables = JSON.parse(readFileSync(join(dataDir, 'seeds.json'), 'utf8')) as SeedTables;
  validateData(catalog, tables);
  return { catalog, tables };
}
